INSERT INTO products (title, slug, description, full_description, price, category, icon, tag, rating, sales, cover_image) VALUES
('CMS интернет-магазина', 'cms-internet-magazina', 'Готовая система управления магазином на PHP: каталог, корзина, заказы, админка.', 'Полноценная CMS для интернет-магазина на PHP. В комплекте: каталог товаров с категориями и фильтрами, корзина, оформление заказа, панель администратора для управления товарами и заказами, интеграция с популярными платёжными системами. Подходит для быстрого запуска магазина любой тематики.', 3490, 'Скрипты', 'ShoppingCart', 'Хит', 5, 214, 'https://cdn.poehali.dev/projects/8c92fcf7-c799-4211-8864-661f0f4257b4/files/fa4eb729-eb45-4dae-83ed-ea7c6149747e.jpg'),
('Скрипт доски объявлений', 'skript-doski-obyavleniy', 'Исходники доски объявлений с модерацией, тарифами и поиском по категориям.', 'Скрипт доски объявлений с системой модерации, платными тарифами размещения, гибким поиском и фильтрацией по категориям. Включена админ-панель для контроля объявлений и пользователей.', 1290, 'Скрипты', 'LayoutList', NULL, 4.8, 138, 'https://cdn.poehali.dev/projects/8c92fcf7-c799-4211-8864-661f0f4257b4/files/f9379359-6664-4704-a77f-a2cd0d5a8df7.jpg'),
('Шаблон лендинга «Про»', 'shablon-lendinga-pro', 'Адаптивный HTML/CSS-шаблон посадочной страницы с анимациями и формой заявки.', 'Современный адаптивный шаблон лендинга с плавными анимациями при скролле, формой заявки и оптимизированной вёрсткой под мобильные устройства. Готов к загрузке контента и запуску рекламы.', 890, 'Шаблоны', 'MonitorSmartphone', 'Новинка', 4.9, 302, 'https://cdn.poehali.dev/projects/8c92fcf7-c799-4211-8864-661f0f4257b4/files/1ac6c8e4-2380-4e42-b056-b3c67219e0d4.jpg'),
('Плагин приёма платежей', 'plagin-priema-platezhey', 'Модуль оплаты AZVOX и ЮMoney с мгновенной выдачей ссылки на скачивание.', 'Готовый плагин для приёма платежей через AZVOX и ЮMoney. Поддерживает мгновенную выдачу ссылки на скачивание после оплаты, обработку webhook-уведомлений и защиту от подделки платежей.', 590, 'Плагины', 'CreditCard', 'AZVOX · ЮMoney', 5, 421, 'https://cdn.poehali.dev/projects/8c92fcf7-c799-4211-8864-661f0f4257b4/files/d6ff5adb-f593-4a86-8574-156b0a5907d2.jpg'),
('Скрипт онлайн-курсов', 'skript-onlayn-kursov', 'Платформа для продажи курсов: уроки, доступы, прогресс и приём оплаты.', 'Платформа для продажи онлайн-курсов с системой уроков, контролем доступа по оплате, отслеживанием прогресса учеников и встроенным приёмом платежей.', 4290, 'Проекты', 'GraduationCap', NULL, 4.7, 76, 'https://cdn.poehali.dev/projects/8c92fcf7-c799-4211-8864-661f0f4257b4/files/1a4476c0-6730-4c18-be8d-b5ef06d05867.jpg'),
('Шаблон корпоративного сайта', 'shablon-korporativnogo-sayta', 'Многостраничный адаптивный шаблон компании: услуги, блог, контакты.', 'Многостраничный шаблон корпоративного сайта: разделы услуг, блог, портфолио и страница контактов. Полностью адаптивен и готов к наполнению.', 1490, 'Шаблоны', 'Building2', NULL, 4.8, 189, 'https://cdn.poehali.dev/projects/8c92fcf7-c799-4211-8864-661f0f4257b4/files/00026888-f46b-44c1-abb2-68c79cbf5086.jpg'),
('Плагин SEO-оптимизации', 'plagin-seo-optimizatsii', 'Мета-теги, карта сайта, микроразметка и человекопонятные URL для PHP-сайтов.', 'SEO-плагин для PHP-сайтов: автогенерация мета-тегов, карты сайта sitemap.xml, микроразметка schema.org и человекопонятные ЧПУ-ссылки для улучшения позиций в поиске.', 690, 'Плагины', 'Search', NULL, 4.6, 154, 'https://cdn.poehali.dev/projects/8c92fcf7-c799-4211-8864-661f0f4257b4/files/f63f3f73-862f-4a82-9d4d-318c8b5e9ed5.jpg'),
('Готовый проект «Каталог услуг»', 'gotovyy-proekt-katalog-uslug', 'Полный исходный код каталога с личным кабинетом, заявками и админкой.', 'Полностью готовый проект каталога услуг с личным кабинетом клиента, системой заявок и админ-панелью для управления услугами и обращениями. Разворачивается «под ключ».', 3990, 'Проекты', 'Package', 'Под ключ', 4.9, 63, 'https://cdn.poehali.dev/projects/8c92fcf7-c799-4211-8864-661f0f4257b4/files/8eca85e6-1059-49eb-838f-27a93a231de5.jpg');
